package app.veyra;
import android.app.Activity;import android.content.Context;import android.content.res.Configuration;import android.view.View;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class FollowWidgetTvTest {
 @Test public void followedSeriesIsScopedAndSurvivesMetadataBackup()throws Exception{Context c=RuntimeEnvironment.getApplication();JSONObject detail=new JSONObject().put("id","42").put("vod_name","Series").put("vod_collection",new JSONArray().put(new JSONObject().put("id","1")).put(new JSONObject().put("id","2")));assertTrue(FollowStore.toggle(c,detail,"current","movie"));JSONObject backup=VelixioData.validate(VelixioData.export(c).toString());String other=ProfileStore.create(c,"Other");ProfileStore.select(c,other);assertTrue(FollowStore.list(c).isEmpty());VelixioData.restore(c,backup);assertEquals(1,FollowStore.list(c).size());}
 @Test public void lowerPartialEpisodeCountsDoNotGenerateFalseFutureGrowth(){assertEquals(10,FollowStore.nextCount(10,4));assertEquals(12,FollowStore.nextCount(10,12));}
 @Test public void privateWidgetDoesNotExposeViewingTitle(){Context c=RuntimeEnvironment.getApplication();app.veyra.data.WatchHistory.remember(c,"current","movie","42","id:1","0","Private title","",5000,90000,false);assertEquals("Private title",ResumeWidget.title(c));c.getSharedPreferences("settings",0).edit().putBoolean("privateWidget",true).commit();assertFalse(ResumeWidget.title(c).contains("Private title"));}
 @Test public void televisionModeUsesLargerCardsAndFocusableControls(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();a.getResources().getConfiguration().uiMode=Configuration.UI_MODE_TYPE_TELEVISION;assertTrue(Ui.tv(a));assertEquals(180,Ui.posterWidth(a));View card=new View(a);Ui.focus(a,card);assertTrue(card.isFocusable());}
 @Test public void audioEffectsNeverAttachToTheGlobalSession(){PlayerAudio audio=new PlayerAudio();assertFalse(audio.attach(0,1));assertFalse(audio.attach(0,2));assertTrue(audio.attach(0,0));audio.close();}
}
